-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_333_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_333_guard;
INSERT INTO _migration_333_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_picture_making_b005_001' AND NOT (q.topic_id IS 'topic_was_picture_making_b005_1' AND q.subject_id IS 'subj_wassce_picture_making' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is line in picture making?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A moving point that defines direction, edge, texture or gesture","B. It creates visible difference and can establish emphasis","C. A colour made by mixing a primary with an adjacent secondary","D. Distant forms appear lighter, cooler and less detailed"]' AND q.correct_answer IS 'A' AND q.explanation IS 'The stated answer applies the governing subject principle directly and distinguishes it from the other same-topic alternatives. Therefore the correct answer is A: A moving point that defines direction, edge, texture or gesture.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_picture_making_b005_1' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_picture_making_b005_001' AND NOT (r.batch_id IS 'wassce-foundation-beta-005' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Picture Making practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2023/12/Arts17.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
